// Assets/Scripts/VersionLabel.cs
//
// Writes the build's own version into a Text at run time, so the number a
// tester reads is the number the build actually carries.
//
// Why this is a component and not a string. The About panel is generated by an
// editor builder and saved into MainMenu.unity, so a version written during
// generation would be a literal baked into the scene: bump the version in
// Player Settings, forget to re-run the builder, and the About screen
// confidently reports the previous release. Application.version is read from
// the built player itself, so the label and the APK cannot disagree.
//
// Attached to the "Version" text by SettingsAboutDialogBuilder.BuildAbout.

using UnityEngine;
using UnityEngine.UI;

[RequireComponent(typeof(Text))]
public class VersionLabel : MonoBehaviour
{
    [Tooltip("Put before the number, so \"v\" reads as \"v0.1.0\".")]
    public string prefix = "v";

    private void Awake()
    {
        Text text = GetComponent<Text>();
        if (text != null)
        {
            text.text = prefix + Application.version;
        }
    }
}
